package org.voxelhorizons.furniture;

import java.util.HashSet;
import java.util.Set;
import java.util.UUID;

/**
 * Deduplicates the block and entity events generated by a single click.
 * The listener clears the set on the next server tick; separate clicks are
 * still allowed to toggle furniture normally.
 */
final class FurnitureInteractionGuard {
    private final Set<String> handled = new HashSet<String>();

    boolean accept(UUID playerId, UUID furnitureId) {
        return handled.add(playerId.toString() + ":" + furnitureId.toString());
    }

    void reset() {
        handled.clear();
    }
}
